package org.sleepwell.app;

import org.junit.Test;
import static org.junit.Assert.*;

public final class NapEngineTest {
 static final class Clock implements NapPlan.Clock {long wall=1792834217345L,elapsed=123456,boot=7;String device="private-test";public long wall(){return wall;}public long elapsed(){return elapsed;}public long boot(){return boot;}public String device(){return device;}void advance(long ms){wall+=ms;elapsed+=ms;}}
 final Clock clock=new Clock();NapEngine.Entry row;boolean failSave,failSchedule,failFire;String access="";int schedules,cancels,fires;long delay;NapPlan last;
 final NapEngine.Repository repo=new NapEngine.Repository(){public NapEngine.Entry load(int id){return id==1?row:null;}public void save(int id,NapPlan p,boolean enabled){if(failSave)throw new IllegalStateException("full");assertEquals(1,id);row=new NapEngine.Entry(p,enabled);}};
 final NapEngine.Port port=new NapEngine.Port(){public String access(){return access;}public void schedule(int id,NapPlan p,long ms){schedules++;last=p;delay=ms;if(failSchedule)throw new IllegalStateException("denied");}public void cancel(int id,NapPlan p){cancels++;}public void fire(int id,NapPlan p){assertFalse(row.enabled);assertEquals(NapPlan.Phase.CLAIMED,row.plan.phase);fires++;if(failFire)throw new IllegalStateException("uncertain");}};
 final NapEngine engine=new NapEngine(repo,port,clock);
 NapPlan arm(){NapPlan p=NapPlan.create(clock,20,0,true);engine.arm(1,p);return p;}
 @Test public void twentyMinuteTimerPreservesMillisecondsAndNeverFloorsToLocalMinute(){NapPlan p=arm();assertEquals(1200000,delay);assertEquals(clock.wall+1200000,p.deadlineWall());clock.advance(1199999);engine.receive(1,p.nonce,false);assertEquals(0,fires);assertEquals(1,delay);clock.advance(1);engine.receive(1,p.nonce,false);assertEquals(1,fires);}
 @Test public void duplicateLateAndReconciledCallbacksCannotDeliverAgain(){NapPlan p=arm();clock.advance(1200000);engine.receive(1,p.nonce,false);engine.receive(1,p.nonce,false);new NapEngine(repo,port,clock).reconcile(1);assertEquals(1,fires);assertFalse(row.enabled);}
 @Test public void cancelledNapPersistsAndCannotReappearAfterProcessRecreation(){NapPlan p=arm();engine.cancel(1,p.nonce);assertEquals(NapPlan.Phase.CANCELLED,row.plan.phase);clock.advance(1200000);new NapEngine(repo,port,clock).receive(1,p.nonce,false);assertEquals(0,fires);assertFalse(row.enabled);}
 @Test public void replacementRejectsOldCancelAndOldDeliveryEvenWhenDue(){NapPlan old=arm();clock.advance(1000);NapPlan replacement=NapPlan.create(clock,10,0,false);engine.arm(1,replacement);engine.cancel(1,old.nonce);engine.receive(1,old.nonce,true);assertEquals(replacement.nonce,row.plan.nonce);assertTrue(row.enabled);assertEquals(0,fires);}
 @Test public void sameBootClockChangesDoNotAlterDurationOrSmartWindow(){NapPlan p=arm();clock.wall+=86400000;assertEquals(1200000,p.remaining(clock));engine.reconcile(1);assertEquals(1200000,delay);assertEquals(clock.wall+1200000,p.projectedDeadline(clock));clock.wall-=172800000;assertEquals(1200000,p.remaining(clock));}
 @Test public void rebootUsesOriginalWallDeadlineWithoutStartingAnotherDuration(){NapPlan p=arm();clock.advance(300000);clock.boot++;clock.elapsed=1;engine.reconcile(1);assertEquals(900000,delay);assertEquals(p.deadlineWall(),clock.wall+delay);}
 @Test public void differentDeviceCannotMistakeMatchingBootNumberForSameBoot(){NapPlan p=arm();clock.advance(100000);clock.device="another-phone";clock.elapsed=1;assertEquals(1100000,p.remaining(clock));}
 @Test public void overdueBootReconcileSchedulesImmediateOwnedDeliveryNotTomorrowOrInlineEffect(){NapPlan p=arm();clock.wall+=86400000;clock.boot++;clock.elapsed=0;engine.reconcile(1);assertEquals(1,delay);assertEquals(0,fires);engine.receive(1,p.nonce,false);assertEquals(1,fires);}
 @Test public void scheduledEntryIncludesFutureDelayAndCannotSmartWakeBeforeStart(){NapPlan p=NapPlan.create(clock,10,3600000,false);engine.arm(1,p);assertEquals(4200000,delay);assertFalse(p.smartReady(clock,60,1,3,100));clock.advance(3600000);assertFalse(p.smartReady(clock,5,1,3,100));clock.advance(300000);assertTrue(p.smartReady(clock,5,1,3,100));}
 @Test public void permissionDeniedRetainsSameTimerForRetryWithoutExtendingIt(){access="Allow alarms";NapPlan p=arm();assertEquals(0,schedules);assertEquals("Allow alarms",row.plan.error);clock.advance(60000);access="";engine.reconcile(1);assertEquals(1140000,delay);assertEquals(p.nonce,row.plan.nonce);assertEquals("",row.plan.error);}
 @Test public void scheduleErrorPersistsAndRecreationRetriesOriginalDeadline(){failSchedule=true;NapPlan p=arm();assertFalse(row.plan.error.isEmpty());clock.advance(120000);failSchedule=false;new NapEngine(repo,port,clock).reconcile(1);assertEquals(1080000,delay);assertEquals(p.nonce,row.plan.nonce);}
 @Test public void failedDurableClaimNeverCallsExternalDelivery(){NapPlan p=arm();clock.advance(1200000);failSave=true;assertThrows(IllegalStateException.class,()->engine.receive(1,p.nonce,false));assertEquals(0,fires);assertEquals(NapPlan.Phase.PENDING,row.plan.phase);}
 @Test public void uncertainDeliveryRemainsClaimedAndCannotBeBlindlyRetried(){NapPlan p=arm();clock.advance(1200000);failFire=true;engine.receive(1,p.nonce,false);assertEquals(1,fires);assertFalse(row.plan.error.isEmpty());engine.receive(1,p.nonce,false);engine.reconcile(1);assertEquals(1,fires);assertEquals(NapPlan.Phase.CLAIMED,row.plan.phase);}
 @Test public void motionGateRequiresRealFiniteSignalSamplesAndTwoActiveMinutesWithinWindow(){NapPlan p=arm();clock.advance(900000);assertFalse(p.smartReady(clock,0,.5,2,30));assertFalse(p.smartReady(clock,5,Double.NaN,2,30));assertFalse(p.smartReady(clock,5,.11,2,30));assertFalse(p.smartReady(clock,5,.5,1,30));assertFalse(p.smartReady(clock,5,.5,2,19));assertTrue(p.smartReady(clock,5,.12,2,20));clock.advance(300000);assertFalse(p.smartReady(clock,5,1,3,100));}
 @Test public void finishedOrDisabledRowRejectsCallbacks(){NapPlan p=arm();row=new NapEngine.Entry(p,false);clock.advance(1200000);engine.receive(1,p.nonce,false);assertEquals(0,fires);row=new NapEngine.Entry(p.state(NapPlan.Phase.FINISHED,""),true);engine.receive(1,p.nonce,false);assertEquals(0,fires);}
 @Test public void rangesAndOverflowFailBeforeScheduling(){assertThrows(IllegalArgumentException.class,()->NapPlan.create(clock,0,0,true));assertThrows(IllegalArgumentException.class,()->NapPlan.create(clock,601,0,true));assertThrows(IllegalArgumentException.class,()->NapPlan.create(clock,20,-1,true));assertThrows(IllegalArgumentException.class,()->NapPlan.create(clock,20,367L*86400000,true));clock.wall=Long.MAX_VALUE-1;assertThrows(ArithmeticException.class,()->NapPlan.create(clock,20,0,true));assertEquals(0,schedules);}
}
